//! 原行の一部の乗数から、元変数箱で下界を別計算する診断。最適化は行わない。
use mip_codex::{mps,model::Model,objective_bound::Certifier};
use std::{collections::BTreeMap,path::PathBuf};
fn main(){let args:Vec<_>=std::env::args().collect();let m=mps::read(&args[1]).unwrap();let lower:Vec<_>=m.variables.iter().map(|v|v.lower_enclosure.map(|x|x[0])).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper_enclosure.map(|x|x[1])).collect();let mut paths:Vec<_>=std::fs::read_dir(&args[2]).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("master-")&&p.extension().is_some_and(|x|x=="json")).collect();paths.sort();
 for p in paths{let v:serde_json::Value=serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();let sources:Vec<(usize,f64)>=serde_json::from_value(v["row_sources"].clone()).unwrap();let weights:Vec<f64>=serde_json::from_value(v["multipliers"].clone()).unwrap();assert_eq!(sources.len(),weights.len());let mut y=BTreeMap::<usize,f64>::new();for((i,s),w)in sources.into_iter().zip(weights){assert!(i<m.rows.len()&&(s==1.||s== -1.));*y.entry(i).or_default()+=s*w;}y.retain(|_,w|*w!=0.);let rows:Vec<_>=y.keys().map(|&i|m.rows[i].clone()).collect();let subset=Model{decimal_source:None,name:m.name.clone(),maximize:m.maximize,offset:m.offset,offset_enclosure:m.offset_enclosure,original_decimal:m.original_decimal,variables:m.variables.clone(),rows};let cert=Certifier::new(&subset).unwrap();let base=cert.bound(&lower,&upper,&vec![0.;y.len()]);let raw:Vec<_>=y.values().copied().collect();let mut best=base;let mut besty=vec![0.;y.len()];let mut trials=0;
  for candidate in [raw.clone(),raw.iter().map(|v|v*(1.-2f64.powi(-40))).collect(),raw.iter().map(|v|v*(1.+2f64.powi(-40))).collect()]{trials+=1;if let Some(b)=cert.bound(&lower,&upper,&candidate){if best.is_none_or(|old|b>old){best=Some(b);besty=candidate;}}}
  for scale in [1.,2.,4.,8.,16.,32.,64.,256.,1024.,1048576.]{let candidate=raw.iter().map(|v|(v*scale).round()/scale).collect::<Vec<_>>();if candidate.iter().any(|v|!v.is_finite()){continue;}trials+=1;if let Some(b)=cert.bound(&lower,&upper,&candidate){if best.is_none_or(|old|b>old){best=Some(b);besty=candidate;}}}
  let multipliers:Vec<_>=y.keys().copied().zip(besty).filter(|(_,v)|*v!=0.).map(|(i,v)|(i,format!("{:016x}",v.to_bits()))).collect();println!("{}",serde_json::json!({"master":p.file_name().unwrap().to_string_lossy(),"rows":subset.rows.len(),"original_variables":m.variables.len(),"original_rows":m.rows.len(),"box_normalized_bound":base,"normalized_bound":best,"normalized_bound_bits":best.map(|b|format!("{:016x}",b.to_bits())),"multipliers":multipliers,"trials":trials,"raw_standard_dual":v["normalized_standard_dual"],"claim":"diagnostic rigorous interval Lagrangian bound; independent exact validation still required; no optimality claim"}));
 }
}
